* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; color: #18323c; background: #19313a; }
body { min-width: 360px; min-height: 100vh; margin: 0; padding: 36px 16px; display: grid; place-items: center; background: radial-gradient(circle at 15% 10%, #34515a 0, transparent 32%), #19313a; }
.board { width: min(100%, 600px); padding: 32px; border: 3px solid #18323c; border-radius: 18px; background: #fffaf0; box-shadow: 7px 8px 0 #10242b; }
.header { text-align: center; }
.pixel-mark { width: 48px; height: 48px; margin: 0 auto 12px; display: grid; place-items: center; border: 3px solid #18323c; border-radius: 12px; color: #18323c; background: #f4c95d; font-size: 26px; box-shadow: 3px 3px 0 #18323c; }
.eyebrow { margin: 0 0 6px; color: #bf653f; font-size: .78rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(1.75rem, 6vw, 2.3rem); line-height: 1.15; letter-spacing: -.04em; }
.subtitle { margin: 10px 0 26px; color: #597078; line-height: 1.5; }
h2 { margin: 0; font-size: 1.1rem; }
.settings { margin-bottom: 24px; padding: 14px 16px; display: flex; justify-content: space-between; align-items: center; gap: 12px; border: 2px solid #d9e1d9; border-radius: 12px; background: #f2f5eb; font-weight: 750; }
.hint { display: block; margin-top: 3px; color: #697b7d; font-size: .78rem; font-weight: 500; }
.tip-control { display: flex; align-items: center; gap: 5px; }
.tip-control input { width: 72px; padding: 8px; text-align: right; }
input { min-height: 44px; border: 2px solid #cbd6d2; border-radius: 9px; color: #18323c; background: #fff; font: inherit; }
input:focus-visible, button:focus-visible { outline: 3px solid #bf653f; outline-offset: 3px; }
.add-section, .items-section { margin-bottom: 24px; }
.add-section h2 { margin-bottom: 12px; }
.item-fields { display: grid; grid-template-columns: 1fr 130px; gap: 10px; }
.item-fields > input { width: 100%; padding: 0 12px; }
.price-input { position: relative; }
.price-input > span { position: absolute; top: 10px; left: 12px; color: #697b7d; }
.price-input input { width: 100%; padding: 0 10px 0 27px; }
.people-picker { min-width: 0; margin: 14px 0; padding: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; border: 0; }
.people-picker legend { width: 100%; margin-bottom: 8px; color: #526a70; font-size: .88rem; font-weight: 700; }
.person-choice { cursor: pointer; }
.person-choice input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.person-choice span { min-height: 42px; padding: 8px 13px; display: inline-flex; align-items: center; border: 2px solid #cbd6d2; border-radius: 999px; background: #fff; font-weight: 700; transition: background .15s, border-color .15s, transform .1s; }
.person-choice input:checked + span { border-color: #18323c; background: #f4c95d; }
.person-choice input:focus-visible + span { outline: 3px solid #bf653f; outline-offset: 3px; }
.person-choice:active span { transform: translateY(1px); }
button { min-height: 46px; border: 2px solid #18323c; border-radius: 10px; color: #fffaf0; background: #18323c; font: inherit; font-weight: 750; cursor: pointer; transition: transform .1s, background .15s, box-shadow .15s; }
button:hover { background: #bf653f; }
button:active { transform: translateY(2px); box-shadow: none; }
.add-button { width: 100%; box-shadow: 0 3px 0 #10242b; }
.add-button span { margin-right: 5px; color: #f4c95d; font-size: 1.2rem; vertical-align: -1px; }
.section-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
.count, .total-note { color: #697b7d; font-size: .85rem; }
.item-list { margin: 10px 0 0; padding: 0; list-style: none; }
.item-row { padding: 12px 0; display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 12px; border-bottom: 1px solid #e4e4d9; }
.item-name { font-weight: 700; overflow-wrap: anywhere; }
.item-people { display: block; margin-top: 3px; color: #697b7d; font-size: .8rem; font-weight: 500; }
.item-price { font-variant-numeric: tabular-nums; font-weight: 750; }
.remove-button { width: 38px; min-height: 38px; color: #8b4c39; background: transparent; box-shadow: none; }
.remove-button:hover { color: white; }
.empty-state { margin: 12px 0 0; padding: 18px 12px; border: 2px dashed #d7ddd4; border-radius: 10px; color: #697b7d; text-align: center; line-height: 1.5; }
.people-totals { margin-top: 12px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; }
.person-total { padding: 12px 8px; border: 2px solid #d9e1d9; border-radius: 11px; background: #f2f5eb; text-align: center; }
.person-total span { display: block; color: #526a70; font-size: .84rem; font-weight: 650; }
.person-total strong { display: block; margin-top: 5px; font-size: 1.15rem; font-variant-numeric: tabular-nums; }
.bill-total { margin-top: 14px; padding-top: 14px; display: flex; justify-content: space-between; border-top: 2px solid #18323c; font-size: 1.08rem; font-weight: 800; }
.bill-total strong { font-variant-numeric: tabular-nums; }
.rounding-note { margin: 10px 0 0; color: #697b7d; font-size: .78rem; line-height: 1.5; }
footer { margin-top: 22px; color: #697b7d; font-size: .8rem; text-align: center; }
footer span { color: #bf653f; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 440px) { body { padding: 18px 10px; } .board { padding: 22px 18px; } .item-fields { grid-template-columns: 1fr 112px; gap: 8px; } .item-row { gap: 8px; } .people-totals { gap: 6px; } .person-total { padding: 11px 4px; } }

const people = ['Alex', 'Blake', 'Casey'];
const items = [];
const form = document.querySelector('#item-form');
const nameInput = document.querySelector('#item-name');
const priceInput = document.querySelector('#item-price');
const tipInput = document.querySelector('#tip');
const list = document.querySelector('#item-list');
const emptyState = document.querySelector('#empty-state');
const count = document.querySelector('#item-count');
const totals = document.querySelector('#people-totals');
const billTotal = document.querySelector('#bill-total');
const money = cents => `$${(cents / 100).toFixed(2)}`;

function render() {
  list.replaceChildren();
  emptyState.hidden = items.length > 0;
  count.textContent = `${items.length} ${items.length === 1 ? 'item' : 'items'}`;

  const tipRate = Math.max(0, Math.min(100, Number(tipInput.value) || 0)) / 100;
  const due = [0, 0, 0];
  let totalCents = 0;

  items.forEach((item, index) => {
    const row = document.createElement('li');
    row.className = 'item-row';
    const details = document.createElement('div');
    const itemName = document.createElement('span');
    itemName.className = 'item-name';
    itemName.textContent = item.name;
    const sharedBy = document.createElement('span');
    sharedBy.className = 'item-people';
    sharedBy.textContent = `Shared by ${item.people.map(person => people[person]).join(', ')}`;
    details.append(itemName, sharedBy);
    const price = document.createElement('span');
    price.className = 'item-price';
    price.textContent = money(item.cents);
    const remove = document.createElement('button');
    remove.className = 'remove-button';
    remove.type = 'button';
    remove.setAttribute('aria-label', `Remove ${item.name}`);
    remove.textContent = '×';
    remove.addEventListener('click', () => { items.splice(index, 1); render(); });
    row.append(details, price, remove);
    list.append(row);

    const shareCount = item.people.length;
    const withTip = Math.round(item.cents * (1 + tipRate));
    totalCents += withTip;
    item.people.forEach(person => { due[person] += withTip / shareCount; });
  });

  totals.replaceChildren();
  people.forEach((person, index) => {
    const card = document.createElement('div');
    card.className = 'person-total';
    const label = document.createElement('span');
    label.textContent = person;
    const amount = document.createElement('strong');
    amount.textContent = money(Math.round(due[index]));
    card.append(label, amount);
    totals.append(card);
  });
  billTotal.textContent = money(totalCents);
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const name = nameInput.value.trim();
  const price = Number(priceInput.value);
  const selected = [...form.querySelectorAll('input[name="person"]:checked')].map(input => Number(input.value));
  if (!name || !Number.isFinite(price) || price <= 0 || selected.length === 0) {
    if (selected.length === 0) form.querySelector('input[name="person"]').focus();
    return;
  }
  items.push({ name, cents: Math.round(price * 100), people: selected });
  form.reset();
  form.querySelector('input[name="person"]').checked = true;
  render();
  nameInput.focus();
});

tipInput.addEventListener('input', render);
render();
